export function PositionFixed({
  top = {{top}},
  right = {{right}},
  label = "{{label}}",
  background = "{{background}}",
}) {
  const lineStyle = { margin: "0 0 34px", fontSize: 12 };
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 300 }}
      role="img" aria-label="A mock browser viewport with scrollable content; the badge is fixed and stays pinned in the same corner while the content underneath scrolls">
      <div style={{ position: "relative", transform: "translateZ(0)", height: 150, overflow: "auto", background: "#FAF7F2", border: "1.5px solid #24143055", borderRadius: 8 }}>
        <div style={{ position: "fixed", top, right, background, padding: "6px 10px", borderRadius: 999, fontSize: 11, fontWeight: 700, boxShadow: "0 4px 10px rgba(36,20,48,.3)" }}>
          {label}
        </div>
        <div style={{ padding: 12 }}>
          <p style={lineStyle}>Scroll this area.</p>
          <p style={lineStyle}>The badge does not move with it.</p>
          <p style={lineStyle}>Line four of filler content.</p>
          <p style={lineStyle}>Line five of filler content.</p>
          <p style={lineStyle}>Line six of filler content.</p>
          <p style={lineStyle}>Line seven of filler content.</p>
        </div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>
        position: fixed; top: {top}px; right: {right}px &mdash; pinned to the viewport, ignores scrolling
      </p>
    </div>
  );
}
